import { createGraph, addEntity, addRelationship } from './graphUtils';

export function integrateMultiAgentOutputs(outputs) {
  const graph = createGraph();

  outputs.forEach(output => {
    const entity = { id: output.id, type: output.type, data: output.data };
    addEntity(graph, entity);

    output.relationships.forEach(rel => {
      addRelationship(graph, rel.source, rel.target, rel.type);
    });
  });

  return graph;
}